#include <bits/stdc++.h>
using namespace std;

struct Point {
    long long x, y;
};

Point operator-(const Point& a, const Point& b) {
    return {a.x - b.x, a.y - b.y};
}

long long dot(const Point& a, const Point& b) {
    return a.x * b.x + a.y * b.y;
}

long long cross(const Point& a, const Point& b) {
    return a.x * b.y - a.y * b.x;
}

long long norm2(const Point& a) {
    return dot(a, a);
}

int main() {
    Point p[7];
    for (auto& point : p) {
        cin >> point.x >> point.y;
    }

    Point base = p[2] - p[1];
    Point v12 = p[1] - p[0];
    Point v13 = p[2] - p[0];

    bool valid = dot(v12, v13) > 0;
    valid &= norm2(p[1] - p[0]) == norm2(p[2] - p[0]);

    for (int i : {3, 4}) {
        valid &= cross(base, p[i] - p[1]) == 0;
    }

    valid &= p[1].x + p[2].x == p[3].x + p[4].x;
    valid &= p[1].y + p[2].y == p[3].y + p[4].y;
    valid &= norm2(base) > norm2(p[4] - p[3]);

    Point v46 = p[5] - p[3];
    Point v57 = p[6] - p[4];
    valid &= dot(base, v46) == 0;
    valid &= dot(base, v57) == 0;
    valid &= norm2(v46) == norm2(v57);

    long long side1 = cross(base, p[0] - p[1]);
    long long side6 = cross(base, p[5] - p[1]);
    valid &= side1 * side6 < 0;

    cout << (valid ? 'S' : 'N') << '\n';
    return 0;
}
